    // 3. 动态注入并初始化
    function injectStoreDOM() {
        if (!document.getElementById('storeAppUI')) {
            const shell = document.querySelector('.iphone') || document.body;
            shell.insertAdjacentHTML('beforeend', storeAppHTML);
        }
    }

    // 获取当前用户面具专属标识，实现多账号数据独立隔离
    function storeGetCurrentUserKey() {
        if (typeof appSettings !== 'undefined' && appSettings.wc_current_user_id) {
            return `mask_${appSettings.wc_current_user_id}`;
        }
        return 'mask_default_guest';
    }

    let boundWorldbookEntryIds = [];

    // All account-scoped store records live in the existing layoutStore.
    let storePendingUserSave = Promise.resolve();
    let storeDataReadyForMask = '';
    let storeDataLoadRevision = 0;
    let storeGenerationRevision = 0;
    let storeFinancialPending = null;

    function storeReadUserSnapshot(userKey) {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open('iOSDesktopDB');
            request.onerror = () => reject(request.error || new Error('Store database unavailable'));
            request.onsuccess = () => {
                const conn = request.result;
                if (!conn.objectStoreNames.contains('layoutStore')) {
                    conn.close();
                    reject(new Error('Store data table unavailable'));
                    return;
                }
                const tx = conn.transaction('layoutStore', 'readonly');
                const get = tx.objectStore('layoutStore').get('store_user_data_' + userKey);
                get.onsuccess = () => resolve(get.result?.data || null);
                get.onerror = () => reject(get.error || new Error('Store record read failed'));
                tx.oncomplete = () => conn.close();
                tx.onabort = () => { conn.close(); reject(tx.error || new Error('Store record read aborted')); };
            };
        });
    }

    function storeBuildUserSnapshot() {
        return JSON.parse(JSON.stringify({
            cart: cartItems,
            addresses: addressList,
            orders: dummyOrders,
            followedStoreIds: followedStoreIds,
            favoriteProductIds: favoriteProductIds,
            userClaimedCouponIds: userClaimedCouponIds,
            browseHistory: browseHistory,
            boundWorldbookEntryIds: boundWorldbookEntryIds,
            mallDatabase: mallDatabase,
            takeoutDatabase: takeoutDatabase,
            brandStoreDatabase: brandStoreDatabase,
            activePinSessions: activePinSessions
        }));
    }

    function storeQueueUserSnapshot(options = {}) {
        const userKey = storeGetCurrentUserKey();
        if (storeDataReadyForMask !== userKey) {
            return Promise.reject(new Error('商城数据尚未成功读取，请重新打开商城后重试'));
        }
        if (storeFinancialPending && !options.settlement) {
            return storeFinancialPending.then(() => {
                if (userKey !== storeGetCurrentUserKey()) return;
                return storeQueueUserSnapshot();
            });
        }
        // Capture the mask and a detached snapshot before queued asynchronous writes.
        const snapshot = options.snapshot || storeBuildUserSnapshot();
        let settledWallet = null;
        const pending = storePendingUserSave.catch(() => {}).then(() => new Promise((resolve, reject) => {
            const request = indexedDB.open('iOSDesktopDB');
            request.onerror = () => reject(request.error || new Error('Store database unavailable'));
            request.onsuccess = () => {
                const conn = request.result;
                if (!conn.objectStoreNames.contains('layoutStore')) {
                    conn.close();
                    reject(new Error('Store data table unavailable'));
                    return;
                }
                const tx = conn.transaction('layoutStore', 'readwrite');
                const table = tx.objectStore('layoutStore');
                let settlementError = null;
                if (options.settlement) {
                    const settlement = options.settlement;
                    const orderGet = table.get('store_user_data_' + userKey);
                    const get = table.get('wechatWalletData_' + settlement.accountId);
                    let orderRead = false, walletRead = false;
                    const settle = () => {
                        if (!orderRead || !walletRead) return;
                        try {
                            if (userKey !== storeGetCurrentUserKey() || settlement.accountId !== wcGetCurrentAccountId()) {
                                throw new Error('账号已切换，本次支付或退款已取消');
                            }
                            const wallet = get.result?.data || get.result;
                            if (!wallet) throw new Error('钱包数据不可用，未发生扣款或退款');
                            const savedOrder = orderGet.result?.data?.orders?.find(item => item.id === settlement.orderId);
                            if (settlement.delta > 0) {
                                if (!savedOrder?.payment || savedOrder.refundedAt ||
                                    savedOrder.paidAmount !== settlement.delta ||
                                    savedOrder.payment.accountId !== settlement.accountId || savedOrder.payment.cardId !== settlement.cardId) {
                                    throw new Error('订单付款或退款记录已变化，请重新打开商城核实');
                                }
                            } else if ((settlement.requireExisting && !savedOrder) ||
                                (savedOrder && savedOrder.status !== 'unpaid')) {
                                throw new Error('订单已处理或已取消，未发生扣款');
                            }
                            settledWallet = JSON.parse(JSON.stringify(wallet));
                            const transactions = settledWallet.transactions || (settledWallet.transactions = []);
                            if (transactions.some(t => t.storeSettlementId === settlement.id)) {
                                throw new Error('该订单已处理，请重新打开商城查看');
                            }
                            const card = settlement.cardId === 'cash' ? null
                                : (settledWallet.familyCards || []).find(c => c.id === settlement.cardId && c.role !== 'sender');
                            if (settlement.cardId !== 'cash' && !card) throw new Error('原支付卡片不可用，未发生扣款或退款');
                            const balance = Number(card ? card.amount : settledWallet.balance);
                            const next = Math.round((balance + settlement.delta) * 100) / 100;
                            if (!Number.isFinite(next) || next < 0) throw new Error('余额不足，未完成支付');
                            if (card) card.amount = next;
                            else settledWallet.balance = next;
                            transactions.unshift({
                                id: settlement.id, storeSettlementId: settlement.id, storeOrderId: settlement.orderId,
                                type: settlement.delta > 0 ? 'income' : 'expense', title: settlement.title,
                                amount: Math.abs(settlement.delta), createdAt: Date.now(), icon: 'money',
                                paymentCardId: settlement.cardId
                            });
                            table.put({ ...settledWallet, id: 'wechatWalletData_' + settlement.accountId });
                            table.put({ id: 'store_user_data_' + userKey, data: snapshot });
                        } catch (error) { settlementError = error; tx.abort(); }
                    };
                    orderGet.onsuccess = () => { orderRead = true; settle(); };
                    get.onsuccess = () => { walletRead = true; settle(); };
                } else {
                    table.put({ id: 'store_user_data_' + userKey, data: snapshot });
                }
                tx.oncomplete = () => { conn.close(); resolve(settledWallet || true); };
                tx.onerror = () => { conn.close(); reject(tx.error || new Error('Store save failed')); };
                tx.onabort = () => { conn.close(); reject(settlementError || tx.error || new Error('Store save aborted')); };
            };
        }));
        storePendingUserSave = pending;
        pending.catch(error => console.warn('Store account data save failed', error));
        return pending;
    }

    function syncStoreDataToDB() {
        storeQueueUserSnapshot().catch(() => {
            if (typeof showToast === 'function') showToast('商城数据保存失败，请检查存储空间');
        });
        queueMicrotask(() => window.dispatchEvent(new Event('tonghuaji:store-orders-changed')));
        return true;
    }

    window.storeFlushForBackup = () => storePendingUserSave;

    function storeOrderAmount(order) {
        const value = order.totalAmount ?? (order.status === 'unpaid'
            ? Number(order.unitPrice ?? order.price) * Number(order.count || 1) : order.price);
        return Math.round(Number(value) * 100) / 100;
    }

    function storeCartAfterPurchase(cart, lines = []) {
        const remaining = cart.map(item => ({ ...item }));
        lines.forEach(line => {
            const index = remaining.findIndex(item => item.id === line.id && item.sku === line.sku);
            if (index < 0) return;
            remaining[index].count -= Number(line.count) || 0;
            if (remaining[index].count <= 0) remaining.splice(index, 1);
        });
        return remaining;
    }

    // Reuse Apple Pay's external-transaction path: wallet and order commit together.
    function storeCommitFinancialOrder(order, settlement, owner, purchasedLines = [], pinSession = null) {
        if (storeFinancialPending) return Promise.reject(new Error('上一笔交易正在保存，请稍后重试'));
        if (owner !== storeGetCurrentUserKey() || storeDataReadyForMask !== owner) {
            return Promise.reject(new Error('账号已切换或商城未能读取，本次交易已取消'));
        }
        const snapshot = storeBuildUserSnapshot();
        const index = snapshot.orders.findIndex(item => item.id === order.id);
        if (index < 0) snapshot.orders.unshift(order);
        else snapshot.orders[index] = order;
        snapshot.cart = storeCartAfterPurchase(snapshot.cart, purchasedLines);
        if (pinSession) snapshot.activePinSessions[pinSession.pinId] = pinSession;
        if (order.refundedAt && order.pinId) delete snapshot.activePinSessions[order.pinId];
        const pending = storeQueueUserSnapshot({ snapshot, settlement }).then(wallet => {
            if (owner !== storeGetCurrentUserKey()) return;
            const live = dummyOrders.find(item => item.id === order.id);
            if (live) Object.assign(live, order);
            else dummyOrders.unshift(order);
            cartItems = storeCartAfterPurchase(cartItems, purchasedLines);
            if (pinSession) activePinSessions[pinSession.pinId] = pinSession;
            if (order.refundedAt && order.pinId) delete activePinSessions[order.pinId];
            if (typeof wcWalletData !== 'undefined') Object.assign(wcWalletData, wallet);
            if (typeof wcRenderWallet === 'function') wcRenderWallet();
            storeRenderCart();
            window.dispatchEvent(new Event('tonghuaji:store-orders-changed'));
        }).finally(() => { if (storeFinancialPending === pending) storeFinancialPending = null; });
        storeFinancialPending = pending;
        return pending;
    }

    async function storeRequestOrderPayment(order, onPaid, title, pinSession = null) {
        const owner = storeGetCurrentUserKey();
        if (!order || storeDataReadyForMask !== owner || typeof wcGetCurrentAccountId !== 'function') {
            if (typeof showToast === 'function') showToast('请先成功读取商城和钱包数据');
            return;
        }
        const accountId = wcGetCurrentAccountId();
        const amount = storeOrderAmount(order);
        if (!Number.isFinite(amount) || amount < 0) {
            if (typeof showToast === 'function') showToast('订单金额无效，未发生扣款');
            return;
        }
        const existed = dummyOrders.some(item => item.id === order.id);
        let completed = false;
        const complete = async paidAmount => {
            if (completed) return;
            if (owner !== storeGetCurrentUserKey() || accountId !== wcGetCurrentAccountId() ||
                (existed && !dummyOrders.some(item => item.id === order.id && item.status === 'unpaid'))) {
                throw new Error('账号或订单状态已变化，未发生扣款');
            }
            if (Math.round(Number(paidAmount) * 100) !== Math.round(amount * 100)) throw new Error('支付金额与订单不一致');
            const cardId = amount === 0 ? 'cash' : (typeof wcApActiveCards !== 'undefined'
                ? wcApActiveCards[wcApActiveCardIndex]?.id : null);
            if (!cardId) throw new Error('请选择可用的支付卡片');
            const paid = {
                ...order, status: 'undelivered', statusText: order.isPinOrder ? '拼单中 · 待成团'
                    : order.orderCategory === 'takeout' ? '骑手正在取餐' : '买家已付款',
                price: amount, totalAmount: amount, paidAmount: amount, paidAt: Date.now(), mapStep: 1,
                payment: { accountId, cardId, settlementId: 'store_pay_' + order.id }
            };
            await storeCommitFinancialOrder(paid, {
                id: paid.payment.settlementId, accountId, cardId, orderId: order.id,
                delta: -amount, title, requireExisting: existed
            }, owner, order.cartLines || [], pinSession);
            completed = true;
            if (owner === storeGetCurrentUserKey()) onPaid(paid);
        };
        try {
            if (amount === 0) await complete(0);
            else if (typeof window.wcOpenApplePay === 'function') {
                await window.wcOpenApplePay({ amount, payee: order.store || '官方自营', title,
                    externalTransaction: true, onSuccess: complete });
            } else if (typeof showToast === 'function') showToast('钱包不可用，未发生扣款');
        } catch (error) {
            if (typeof showToast === 'function') showToast(error.message || '支付未完成，请重试');
        }
    }

    async function initStoreDataFromDB() {
        await storePendingUserSave.catch(() => {});
        const userKey = storeGetCurrentUserKey();
        const revision = ++storeDataLoadRevision;
        ++storeGenerationRevision;
        storeDataReadyForMask = '';
        const oldKey = 'store_user_data_' + userKey;
        let saved = null;
        let fromLegacy = false;
        try {
            saved = await storeReadUserSnapshot(userKey);
        } catch(error) {
            console.warn('Store account data read failed', error);
            if (typeof showToast === 'function') showToast('商城数据读取失败，请检查设备存储');
            throw error;
        }
        if (!saved) {
            try {
                const oldRaw = localStorage.getItem(oldKey);
                if (oldRaw) {
                    saved = JSON.parse(oldRaw);
                    fromLegacy = true;
                }
            } catch(error) {
                console.warn('Legacy store data read failed', error);
                throw error;
            }
        }

        if (userKey !== storeGetCurrentUserKey() || revision !== storeDataLoadRevision) {
            throw new Error('商城账号已切换，请重新打开商城');
        }

        // Reset account-scoped state before loading the next mask.
        mallDatabase = JSON.parse(JSON.stringify(storeInitialCatalog.mall));
        takeoutDatabase = JSON.parse(JSON.stringify(storeInitialCatalog.takeout));
        brandStoreDatabase = JSON.parse(JSON.stringify(storeInitialCatalog.brands));
        cartItems = [];
        addressList = [];
        dummyOrders = [];
        followedStoreIds = [];
        favoriteProductIds = [];
        userClaimedCouponIds = ['cp_mall_newbie', 'cp_takeout_newbie'];
        browseHistory = [];
        boundWorldbookEntryIds = [];
        activePinSessions = {};
        currentDetailProduct = null;
        currentTakeoutShop = null;
        currentBrandShop = null;
        currentTakeoutOrderDraft = null;
        currentPendingOrderId = null;
        storeCheckoutCartDraft = null;
        takeoutCartItems = [];
        takeoutCartTotal = 0;

        if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
            if (Array.isArray(saved.cart)) cartItems = saved.cart;
            if (Array.isArray(saved.addresses)) addressList = saved.addresses;
            if (Array.isArray(saved.orders)) {
                dummyOrders = saved.orders.filter(order => order && order.id && order.createdAt &&
                    !String(order.id).includes('mock') && !String(order.id).includes('placeholder'));
            }
            if (Array.isArray(saved.followedStoreIds)) followedStoreIds = saved.followedStoreIds;
            if (Array.isArray(saved.favoriteProductIds)) favoriteProductIds = saved.favoriteProductIds;
            if (Array.isArray(saved.userClaimedCouponIds)) userClaimedCouponIds = saved.userClaimedCouponIds;
            if (Array.isArray(saved.browseHistory)) browseHistory = saved.browseHistory.filter(item => item && item.id && !item.isPlaceholder && item.title);
            if (Array.isArray(saved.boundWorldbookEntryIds)) boundWorldbookEntryIds = saved.boundWorldbookEntryIds;
            if (Array.isArray(saved.mallDatabase)) mallDatabase = saved.mallDatabase;
            if (Array.isArray(saved.takeoutDatabase)) takeoutDatabase = saved.takeoutDatabase;
            if (Array.isArray(saved.brandStoreDatabase)) brandStoreDatabase = saved.brandStoreDatabase;
            if (saved.activePinSessions && typeof saved.activePinSessions === 'object' && !Array.isArray(saved.activePinSessions)) {
                activePinSessions = saved.activePinSessions;
            }
        }
        dummyOrders.forEach(order => {
            if (order.status !== 'unpaid' || order.totalAmount != null) return;
            order.unitPrice = Number(order.price);
            order.subtotal = Math.round(order.unitPrice * Number(order.count || 1) * 100) / 100;
            order.totalAmount = order.subtotal;
            order.price = order.totalAmount;
        });
        storeUpgradeLegacyCatalogPhotos();
        storeRefreshDynamicCoupons();
        storeCatalogLoadedForMask = userKey;
        storeDataReadyForMask = userKey;

        if (fromLegacy) {
            try {
                await storeQueueUserSnapshot();
                localStorage.removeItem(oldKey);
            } catch(error) {
                console.warn('Legacy store migration was not confirmed; old data retained', error);
                if (typeof showToast === 'function') showToast('商城旧数据迁移失败，旧数据已保留');
            }
        }
    }

        // ================= AI 结合世界书条目生成商城内容核心逻辑 =================
    const STORE_DEFAULT_GEN_PROMPT = `严格依据绑定的世界书角色设定、地域文化、特产与世界观风格，深度策划并生成：
1. 品牌店铺：包含店铺名称、特色短语、粉丝量与黑标/认证标签；
2. 专属商品：为每家店铺生成专属好物，包含吸引人的商品标题、价格、销量，必须生成贴合该商品品类属性的 2~3 个专属规格（specs，例如尺码、容量、配色、轴体等，严禁统一千篇一律为典藏版），并生成 2~3 条贴合商品属性与世界观的真实买家评价（reviews）；
3. 特色外卖：包含特色餐饮外卖店与旗下 3~4 道招牌美食餐品（dishes）。`;

    window.storeToggleAIPromptFold = function () {
        const foldCard = document.getElementById('storeAIPromptFoldCard');
        if (foldCard) {
            foldCard.classList.toggle('expanded');
        }
    };

    window.storeResetDefaultPrompt = function () {
        const promptInput = document.getElementById('storeAICustomPromptInput');
        if (promptInput) {
            promptInput.value = STORE_DEFAULT_GEN_PROMPT;
            if (typeof showToast === 'function') showToast('已恢复默认提示词');
        }
    };

    window.storeOpenAIGenModal = function () {
        const modal = document.getElementById('storeAIGenModal');
        if (!modal) return;
        const countTip = document.getElementById('storeAIGenBoundCountTip');
        if (countTip) {
            const count = Array.isArray(boundWorldbookEntryIds) ? boundWorldbookEntryIds.length : 0;
            countTip.innerText = count > 0 ? `${count} 个条目` : '未绑定 (将使用全部活跃词条)';
        }
        const promptInput = document.getElementById('storeAICustomPromptInput');
        if (promptInput && !promptInput.value.trim()) {
            promptInput.value = STORE_DEFAULT_GEN_PROMPT;
        }
        const formBody = document.getElementById('storeAIGenFormBody');
        const loadingBox = document.getElementById('storeAIGenLoadingBox');
        const footActions = document.getElementById('storeAIGenFootActions');
        if (formBody) formBody.style.display = 'flex';
        if (loadingBox) loadingBox.style.display = 'none';
        if (footActions) footActions.style.display = 'flex';
        modal.classList.add('show');
    };

    window.storeCloseAIGenModal = function () {
        const modal = document.getElementById('storeAIGenModal');
        if (modal) modal.classList.remove('show');
    };

    window.storeAdjustAIGenNum = function (type, delta) {
        let input = null;
        if (type === 'product') input = document.getElementById('storeAIGenProductCount');
        else if (type === 'store') input = document.getElementById('storeAIGenStoreCount');
        else if (type === 'takeout') input = document.getElementById('storeAIGenTakeoutCount');
        if (!input) return;
        let val = parseInt(input.value, 10) || 4;
        const min = parseInt(input.min, 10) || 1;
        const max = parseInt(input.max, 10) || 20;
        val = Math.max(min, Math.min(max, val + delta));
        input.value = val;
    };

    window.storeStartAIGeneration = async function () {
        const owner = storeGetCurrentUserKey();
        if (storeDataReadyForMask !== owner) {
            if (typeof showToast === 'function') showToast('请先成功读取商城数据后再生成');
            return;
        }
        const generationRevision = ++storeGenerationRevision;
        // 1. 获取当前系统配置的可用 API 连接
        const apis = window.apiDataList || (typeof apiDataList !== 'undefined' ? apiDataList : []);
        const currentConnectedId = (typeof apiConnectedId !== 'undefined') ? apiConnectedId : (apis[0]?.id);
        const currentApi = apis.find(a => a.id === currentConnectedId) || apis[0];

        if (!currentApi || !currentApi.url || !currentApi.key) {
            if (typeof showToast === 'function') showToast('请先在【设置】->【API连接】中配置可用接口');
            else alert('请先在【设置】->【API连接】中配置可用接口');
            return;
        }

        // 2. 收集绑定的世界书内容
        const allWb = (typeof wbEntries !== 'undefined' && Array.isArray(wbEntries))
            ? wbEntries.filter(e => !e.isDeleted)
            : ((window.wbEntries || []).filter(e => !e.isDeleted));

        let targetEntries = [];
        if (Array.isArray(boundWorldbookEntryIds) && boundWorldbookEntryIds.length > 0) {
            targetEntries = allWb.filter(e => boundWorldbookEntryIds.includes(e.id));
        }
        if (targetEntries.length === 0) {
            targetEntries = allWb.slice(0, 10);
        }

        let wbContextText = "";
        if (targetEntries.length > 0) {
            wbContextText = targetEntries.map(e => `【${e.title || '词条'}】(关键词: ${e.key || '无'})\n${e.content || ''}`).join('\n\n');
        } else {
            wbContextText = "当前无特定世界书，请自由发挥创意创造一个现代化潮流、具有设计师审美或奇幻风格的精品商城。";
        }

        const perStoreProdCount = parseInt(document.getElementById('storeAIGenProductCount')?.value, 10) || 3;
        const storeCount = parseInt(document.getElementById('storeAIGenStoreCount')?.value, 10) || 3;
        const takeoutCount = parseInt(document.getElementById('storeAIGenTakeoutCount')?.value, 10) || 3;

        // UI 切换为加载状态，同时在页面上方唤出灵动胶囊提示
        const formBody = document.getElementById('storeAIGenFormBody');
        const loadingBox = document.getElementById('storeAIGenLoadingBox');
        const footActions = document.getElementById('storeAIGenFootActions');
        const statusEl = document.getElementById('storeAIGenLoadingStatus');
        const topIsland = document.getElementById('storeTopIslandPill');
        const topIslandText = document.getElementById('storeTopIslandText');

        if (formBody) formBody.style.display = 'none';
        if (loadingBox) loadingBox.style.display = 'flex';
        if (footActions) footActions.style.display = 'none';
        if (statusEl) statusEl.innerText = `正在连接 ${currentApi.model || '大模型'}...`;
        if (topIsland) {
            if (topIslandText) topIslandText.innerText = "正在努力生成商品与店铺...";
            topIsland.classList.add('show');
        }

        try {
            const customPromptText = document.getElementById('storeAICustomPromptInput')?.value.trim() || STORE_DEFAULT_GEN_PROMPT;
            const prompt = `你是一个顶级电商平台策划总监。请依据以下【世界书背景设定】：
---
${wbContextText}
---

【具体策划要求】：
${customPromptText}

【生成配额数量】：
1. 生成 ${storeCount} 家独具特色的品牌店铺。
2. 每家店铺旗下同步生成 ${perStoreProdCount} 件专属商品，每件商品附带 2~3 个品类专属真实规格（specs，禁止千篇一律搞典藏版）与 2~3 条真实买家评价（reviews）。
3. 生成 ${takeoutCount} 家餐饮外卖店铺，每家外卖店必须包含 3~4 道招牌美食餐品（dishes）。

必须仅输出一个纯 JSON 对象，格式严格如下，不要输出任何多余的解释或 markdown：
{
  "stores": [
    {
      "id": 301,
      "name": "店铺名称（如：赛博声学工坊、云端制茶社）",
      "badge": "官方认证/黑标神店/金牌精选/主理人品牌",
      "fans": "24.6万粉丝",
      "desc": "店铺特色短语描述",
      "logo": "ARC (2到4位英文大写简写)",
      "products": [
        {
          "id": 1,
          "title": "完整商品标题（具有吸引力、包含核心亮点）",
          "price": 259.00,
          "sales": "1.2万+付款",
          "tag": "官方正品",
          "specs": [
            { "name": "贴合该商品的常规规格1（如：曜石黑 / 42码）", "extra": 0 },
            { "name": "贴合该商品的进阶规格2（如：银灰限定 / 43码）", "extra": 20 }
          ],
          "reviews": [
            { "user": "买家***7", "star": "★★★★★", "date": "2026-09-20", "sku": "对应规格1", "content": "真实具体的使用评价与反馈..." },
            { "user": "用户***3", "star": "★★★★★", "date": "2026-09-18", "sku": "对应规格2", "content": "收到实物很惊喜，包装与做工非常契合..." }
          ]
        }
      ]
    }
  ],
  "takeout": [
    {
      "id": 201,
      "name": "外卖餐厅名称（含特色分店名）",
      "rating": 4.9,
      "monthSales": "月售 2400+",
      "time": "25分钟",
      "distance": "1.2km",
      "minPrice": 20,
      "deliveryFee": "免配送费",
      "tags": ["满30减5", "热销第一名", "支持准时达"],
      "dishes": [
        { "name": "招牌特色主食/菜品名称", "desc": "食材搭配与口感特色短句", "price": 28.00 },
        { "name": "特色饮品或佐餐小食", "desc": "独家秘制风味", "price": 12.00 }
      ]
    }
  ]
}`;

            const baseUrl = currentApi.url.endsWith('/') ? currentApi.url.slice(0, -1) : currentApi.url;
            const endpoint = /\/chat\/completions$/i.test(baseUrl) ? baseUrl : `${baseUrl}/chat/completions`;

            const resp = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${currentApi.key}`
                },
                body: JSON.stringify({
                    model: currentApi.model || 'gpt-3.5-turbo',
                    messages: [
                        { role: 'system', content: 'You are an AI that outputs only strictly valid JSON without any markdown formatting or explanations.' },
                        { role: 'user', content: prompt }
                    ],
                    temperature: 0.7
                })
            });

            if (!resp.ok) {
                throw new Error(`API 响应错误 HTTP ${resp.status}`);
            }

            const resData = await resp.json();
            const rawContent = resData?.choices?.[0]?.message?.content || '';
            const cleaned = rawContent.replace(/```json/gi, '').replace(/```/g, '').trim();

            const parsed = JSON.parse(cleaned);

            if (owner !== storeGetCurrentUserKey() || generationRevision !== storeGenerationRevision ||
                storeDataReadyForMask !== owner) {
                throw new Error('账号或商城数据已切换，本次生成结果未写入');
            }

            if (!parsed || (!parsed.products && !parsed.stores && !parsed.takeout)) {
                throw new Error('返回的 JSON 数据结构不完整');
            }

            // 联动解析：生成店铺 -> 同步生成其旗下的商品与评价
            const newBrandStores = [];
            const newMallProducts = [];
            let nextCatalogId = storeCatalogNewId();

            if (Array.isArray(parsed.stores) && parsed.stores.length > 0) {
                for (let sIdx = 0; sIdx < parsed.stores.length; sIdx++) {
                    const store = parsed.stores[sIdx];
                    const storeId = nextCatalogId++;
                    const storeName = store.name || "品牌设计馆";
                    const storeLogoClean = (store.logo || storeName).slice(0, 4).toUpperCase();
                    const storeBadge = store.badge || "官方认证";
                    const storeDesc = store.desc || "品质造物 · 官方旗舰";

                    const storeProducts = [];
                    const rawProds = Array.isArray(store.products) ? store.products : [];

                    for (let pIdx = 0; pIdx < rawProds.length; pIdx++) {
                        const p = rawProds[pIdx];
                        const pid = nextCatalogId++;
                        // Use the existing category-matched photo pool without requesting image generation.
                        const prodImg = storeFindMatchedRealPhoto(p.title || storeName, 'product');
                        const prodSpecs = Array.isArray(p.specs) && p.specs.length > 0 ? p.specs : [
                            { name: "标准款 / 官方默认", extra: 0 },
                            { name: "进阶高配版", extra: 30 }
                        ];

                        const prodItem = {
                            id: pid,
                            storeId: storeId,
                            storeName: storeName,
                            storeLogo: storeLogoClean,
                            storeBadge: storeBadge,
                            storeDesc: storeDesc,
                            title: p.title || "精选好物",
                            price: parseFloat(p.price) || 199.00,
                            sales: p.sales || "2000+付款",
                            tag: p.tag || "官方正品",
                            img: prodImg,
                            photoSource: 'matched',
                            specs: prodSpecs,
                            reviews: Array.isArray(p.reviews) && p.reviews.length > 0 ? p.reviews : [
                                { user: "买家***7", star: "★★★★★", date: "2026-09-22", sku: prodSpecs[0].name, content: "做工质感一流，设计细节十分考究，非常符合预期！" },
                                { user: "用户***1", star: "★★★★★", date: "2026-09-19", sku: prodSpecs[0].name, content: "物流很快，包装完整，正品保证值得信赖。" }
                            ]
                        };
                        newMallProducts.push(prodItem);
                        storeProducts.push({
                            id: pid,
                            title: prodItem.title,
                            price: String(prodItem.price),
                            img: prodImg,
                            photoSource: prodItem.photoSource
                        });
                    }

                    newBrandStores.push({
                        id: storeId,
                        name: storeName,
                        badge: storeBadge,
                        fans: store.fans || "18.5万粉丝",
                        desc: storeDesc,
                        logo: storeGenerateLogoSvg(storeLogoClean),
                        products: storeProducts
                    });
                }
            }

            if (newMallProducts.length > 0) {
                // 提取旧库中已被加入购物车或者被收藏的商品，避免被新生成的商品覆盖抹除
                const keepProductIds = new Set([
                    ...cartItems.map(c => c.id),
                    ...mallDatabase.filter(p=>p.isCustom).map(p=>p.id),
                    ...favoriteProductIds
                ]);
                const preservedOldProds = mallDatabase.filter(p => keepProductIds.has(p.id) && !newMallProducts.some(np => np.id === p.id));
                mallDatabase = [...newMallProducts, ...preservedOldProds];
            }
            if (newBrandStores.length > 0) {
                // 提取旧库中已被关注的店铺，安全保留不被覆盖
                const preservedOldStores = brandStoreDatabase.filter(s => (s.isCustom || followedStoreIds.includes(s.id) || mallDatabase.some(p => p.storeId === s.id)) && !newBrandStores.some(ns => ns.id === s.id));
                brandStoreDatabase = [...newBrandStores, ...preservedOldStores];
            }

            // 联动解析：外卖店铺 -> 同步生成其旗下的美食餐品（分类图库匹配）
            if (Array.isArray(parsed.takeout) && parsed.takeout.length > 0) {
                const newTakeoutList = [];
                for (let idx = 0; idx < parsed.takeout.length; idx++) {
                    const t = parsed.takeout[idx];
                    const takeoutId = nextCatalogId++;
                    const rawDishes = Array.isArray(t.dishes) ? t.dishes : [];
                    const shopImg = storeFindMatchedRealPhoto(t.name || 'food shop', 'takeout');
                    const dishList = [];

                    for (let dIdx = 0; dIdx < rawDishes.length; dIdx++) {
                        const dish = rawDishes[dIdx];
                        const dishImg = storeFindMatchedRealPhoto(dish.name || 'delicious food', 'dish');
                        dishList.push({
                            id: nextCatalogId++,
                            name: dish.name || "招牌美味精选",
                            desc: dish.desc || "香气扑鼻 · 现做现发",
                            price: parseFloat(dish.price) || 25.00,
                            img: dishImg,
                            photoSource: 'matched'
                        });
                    }

                    newTakeoutList.push({
                        id: takeoutId,
                        name: t.name || "特色美食工坊",
                        rating: parseFloat(t.rating) || 4.8,
                        monthSales: t.monthSales || "月售 1000+",
                        time: t.time || "28分钟",
                        distance: t.distance || "1.2km",
                        minPrice: parseInt(t.minPrice, 10) || 20,
                        deliveryFee: t.deliveryFee || "免配送费",
                        tags: Array.isArray(t.tags) && t.tags.length > 0 ? t.tags : ["满30减5", "品质优选"],
                        img: shopImg,
                        photoSource: 'matched',
                        dishes: dishList
                    });
                }
                takeoutDatabase = [...newTakeoutList,...takeoutDatabase.filter(t=>t.isCustom && !newTakeoutList.some(n=>n.id===t.id))];
            }

            // Assign distinct stock photos after loading the newly generated catalog.
            storeUpgradeLegacyCatalogPhotos();
            // 同步刷新跟随新商品/店铺/外卖的全新动态优惠券池
            storeRefreshDynamicCoupons();

            // 同步保存，刷新各模块视图
            await storeQueueUserSnapshot();
            storeRenderMallProducts();
            storeRenderBrandStores();
            storeRenderTakeoutShops();

            storeCloseAIGenModal();
            if (topIsland) topIsland.classList.remove('show');

            if (typeof showToast === 'function') {
                showToast(`已依据世界书生成 ${brandStoreDatabase.length} 家店铺(${mallDatabase.length} 件商品与评价)及 ${takeoutDatabase.length} 家外卖菜单！`);
            }
        } catch (err) {
            console.error('AI 生成商城内容失败:', err);
            if (formBody) formBody.style.display = 'flex';
            if (loadingBox) loadingBox.style.display = 'none';
            if (footActions) footActions.style.display = 'flex';
            if (topIsland) topIsland.classList.remove('show');
            if (typeof showToast === 'function') {
                showToast(`生成失败: ${err.message || '网络异常'}`);
            } else {
                alert(`生成失败: ${err.message || '网络异常'}`);
            }
        }
    };

    // 4. Business entry: the desktop pointer session already consumes the opening gesture,
    // so the store can remain interactive immediately after it becomes visible.
    window.openStoreApp = async function () {
        injectStoreDOM();
        const storeUI = document.getElementById('storeAppUI');
        if (!storeUI) return;

        storeUI.style.pointerEvents = 'auto';
        storeUI.style.display = 'flex';

        if (!storeUI.dataset.imageFallbackReady) {
            storeUI.dataset.imageFallbackReady = '1';
            storeUI.addEventListener('error', event => {
                const img = event.target;
                if (!img || img.tagName !== 'IMG' || img.dataset.storeFallbackDone) return;
                if (img.dataset.storePhotoType) {
                    storeHandleSmartImageError(img);
                    return;
                }
                // Editing previews must never silently replace the user's chosen URL.
                if (/^storeEdit/.test(img.id)) return;
                img.dataset.storeFallbackDone = '1';
                img.src = storeGenerateCoverSvg('apparel');
            }, true);
        }

        // 自动从微信当前登录态同步账号，避免明明登录了微信却误判为未登录
        if (typeof wcGetAuthData === 'function') {
            try {
                const authData = await wcGetAuthData();
                if (authData && authData.currentLoginWxid && Array.isArray(authData.accounts)) {
                    const currentAcc = authData.accounts.find(a => a.wxid === authData.currentLoginWxid);
                    if (currentAcc && typeof appSettings !== 'undefined') {
                        appSettings.wc_current_user_id = currentAcc.maskId || currentAcc.wxid;
                        appSettings.wc_current_user_name = currentAcc.name;
                        appSettings.wc_current_user_avatar = currentAcc.avatar || '';
                        appSettings.wc_current_user_phone = currentAcc.wxid || currentAcc.phone || '';
                        if (typeof saveAppSettings === 'function') saveAppSettings();
                    }
                }
            } catch (e) {}
        }

        await storeLoadAppearance();
        const isUserLogged = !!(typeof appSettings !== 'undefined' && appSettings.wc_current_user_id && appSettings.wc_current_user_name);
        const bottomBar = storeUI.querySelector('.store-app-bottom-bar');

        if (!isUserLogged) {
            if (bottomBar) bottomBar.style.display = 'none';
            storeOpenLoginSubpage();
        } else {
            if (bottomBar) bottomBar.style.display = 'flex';
            if (typeof wcLoadWalletData === 'function') {
                wcLoadWalletData().catch(() => {});
            }
            try {
                await initStoreDataFromDB();
            } catch (error) {
                closeStoreApp();
                if (typeof showToast === 'function') showToast('商城数据未能读取，已保留原数据，请重新打开重试');
                return;
            }
            storeRenderMallProducts();
            storeRenderBrandStores();
            storeRenderTakeoutShops();
            storeRenderCart();
            storeSwitchOrderType('mall');
            syncUserProfile();
        }

        storeUI.classList.add('show');
    };

    window.closeStoreApp = function () {
        const storeUI = document.getElementById('storeAppUI');
        if (!storeUI) return;
        storeUI.classList.remove('show');
        // 关键3：即时隐藏，消除350ms假卡顿与空等待
        storeUI.style.display = 'none';
        if (typeof window.syncStatusBarAfterReturnHome === 'function') {
            window.syncStatusBarAfterReturnHome();
        }
    };

    window.storeNavigate = function (tabId) {
        const tabs = ['mall', 'shop', 'takeout', 'wish', 'user'];
        tabs.forEach((id, idx) => {
            const btn = document.querySelectorAll('.store-app-bottom-bar .store-tab-btn')[idx];
            if (btn) btn.classList.toggle('store-active', id === tabId);
        });

        // 视图映射：shop 独立映射至 shop 页面，wish 映射至购物车，其他保持对应
        const panelMap = {
            mall: 'mall',
            shop: 'shop',
            takeout: 'takeout',
            wish: 'cart',
            user: 'user'
        };
        const targetPanel = panelMap[tabId] || 'mall';
        ['mall', 'shop', 'takeout', 'msg', 'cart', 'user'].forEach(pid => {
            const panel = document.getElementById(`store-panel-${pid}`);
            if (panel) panel.classList.toggle('store-active', pid === targetPanel);
        });

        const viewport = document.getElementById('storeMainViewport');
        if (viewport) viewport.scrollTo(0, 0);

        if (targetPanel === 'shop') {
            storeRenderBrandStores();
        }
        if (targetPanel === 'cart') {
            storeRenderCart();
        }
        if (targetPanel === 'user') {
            storeSwitchOrderType('mall');
            syncUserProfile();
        }
    };

    function syncUserProfile() {
        const nameEl = document.getElementById('storeProfileNameTitle');
        const avatarEl = document.getElementById('storeProfileAvatarImg');
        const isGuest = !appSettings?.wc_current_user_id && !appSettings?.wc_current_user_name;

        if (isGuest) {
            if (nameEl) {
                nameEl.innerHTML = `未登录 <span style="font-size:11px; font-weight:normal; color:#0071e3; cursor:pointer;" onclick="storeOpenLoginSubpage()">点击登录</span>`;
            }
            if (avatarEl) {
                avatarEl.src = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='100'><rect width='100%' height='100%' fill='%23d1d1d6'/></svg>";
                avatarEl.onclick = storeOpenLoginSubpage;
                avatarEl.style.cursor = 'pointer';
            }
            return;
        }

        if (typeof appSettings !== 'undefined') {
            const currentName = appSettings.wc_current_user_name || appSettings.apple_id_name || '会员用户';
            const currentAvatar = appSettings.wc_current_user_avatar || appSettings.apple_id_avatar || "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='100'><rect width='100%' height='100%' fill='%23f2f2f7'/></svg>";
            if (nameEl) {
                nameEl.innerText = currentName;
            }
            if (avatarEl) {
                avatarEl.src = currentAvatar;
                avatarEl.onclick = null;
                avatarEl.style.cursor = 'default';
            }
        }
    }

    // 快捷登录页面控制与逻辑
    window.storeOpenLoginSubpage = async function () {
        const page = document.getElementById('storeLoginSubpage');
        const mount = document.getElementById('storeLoginAccountsListMount');
        if (!page) return;

        let accounts = [];
        try {
            if (typeof wcGetAuthData === 'function') {
                const authData = await wcGetAuthData();
                accounts = Array.isArray(authData?.accounts) ? authData.accounts : [];
            }
        } catch (e) {
            console.warn('获取候选登录账号失败:', e);
        }

        // 尝试从通讯录/用户面具列表读取真实用户
        if (accounts.length === 0 && window.ContactsApp && typeof window.ContactsApp.getUsers === 'function') {
            try {
                const uList = await window.ContactsApp.getUsers();
                if (Array.isArray(uList) && uList.length > 0) {
                    accounts = uList.map(u => ({
                        maskId: u.id || `mask_${Date.now()}`,
                        name: u.name,
                        avatar: u.avatar || '',
                        wxid: u.phone || u.account || 'wx_user'
                    }));
                }
            } catch (e) {}
        }

        // 若当前 appSettings 中有真实的当前账号，作为可选账号
        if (accounts.length === 0 && typeof appSettings !== 'undefined' && (appSettings.wc_current_user_name || appSettings.wc_current_user_id)) {
            accounts = [{
                maskId: appSettings.wc_current_user_id || 'user_current',
                name: appSettings.wc_current_user_name || '微信用户',
                avatar: appSettings.wc_current_user_avatar || '',
                wxid: appSettings.wc_current_user_phone || 'wxid_user'
            }];
        }

        // 彻底杜绝伪造“林小悦”：无账号时显示明确的暂无账号空状态提示
        if (mount) {
            if (accounts.length === 0) {
                mount.innerHTML = `
                    <div class="store-login-empty-box">
                        <div class="store-login-empty-icon">
                            <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="#8e8e93" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
                                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                                <circle cx="12" cy="7" r="4"></circle>
                            </svg>
                        </div>
                        <div class="store-login-empty-title">暂无账号面具</div>
                        <div class="store-login-empty-desc">系统中尚未检测到你创建的微信账号，请先前往微信或通讯录创建你的专属面具账号。</div>
                        <button type="button" class="store-login-goto-wc-btn" onclick="storeGoToCreateWeChatAccount()">前往微信创建账号</button>
                    </div>
                `;
            } else {
                mount.innerHTML = accounts.map(acc => `
                    <div class="store-login-account-card" onclick="storeSelectAccountLogin('${acc.wxid || acc.maskId}')">
                        <div class="store-login-card-avatar">
                            <img src="${acc.avatar || 'data:image/svg+xml;utf8,<svg xmlns=\'http://www.w3.org/2000/svg\' width=\'100\' height=\'100\'><rect width=\'100%\' height=\'100%\' fill=\'%23d1d1d6\'/></svg>'}" alt="">
                        </div>
                        <div class="store-login-card-meta">
                            <div class="store-login-card-name">${acc.name || '微信用户'}</div>
                            <div class="store-login-card-wxid">微信号：${acc.wxid || 'wxid_user'}</div>
                        </div>
                        <button type="button" class="store-login-enter-pill">直接登录</button>
                    </div>
                `).join('');
            }
        }

        page.classList.add('store-login-active');
    };

    // 前往微信创建账号引导
    window.storeGoToCreateWeChatAccount = function () {
        closeStoreApp();
        if (typeof window.openWeChatApp === 'function') {
            window.openWeChatApp();
        } else if (typeof window.openWeChat === 'function') {
            window.openWeChat();
        } else if (typeof showToast === 'function') {
            showToast('请在微信中点击【我】->【设置】创建或切换面具账号');
        }
    };

    window.storeCloseLoginSubpage = function () {
        const page = document.getElementById('storeLoginSubpage');
        if (page) page.classList.remove('store-login-active');
    };

    // 登录页左上角 < 按钮行为
    window.storeLoginBackAction = function () {
        const isUserLogged = !!(typeof appSettings !== 'undefined' && appSettings.wc_current_user_id && appSettings.wc_current_user_name);
        if (!isUserLogged) {
            // 未登录状态下点击返回直接退出整个商城 App 回到手机桌面
            closeStoreApp();
        } else {
            storeCloseLoginSubpage();
        }
    };

    // 点击卡片直接以该面具身份登录（修复登录后仍然显示未登录的问题）
    window.storeSelectAccountLogin = async function (identifier) {
        try {
            let targetAcc = null;

            // 1. 查找匹配的真实账号信息
            if (typeof wcGetAuthData === 'function') {
                try {
                    const authData = await wcGetAuthData();
                    const accs = Array.isArray(authData?.accounts) ? authData.accounts : [];
                    targetAcc = accs.find(a => a.wxid === identifier || a.maskId === identifier);
                    if (targetAcc) {
                        authData.currentLoginWxid = targetAcc.wxid;
                        if (typeof wcSaveAuthData === 'function') {
                            await wcSaveAuthData(authData);
                        }
                    }
                } catch (e) {}
            }

            // 2. 若有微信切换接口，执行切换
            if (typeof wcSwitchToAccount === 'function') {
                try {
                    await wcSwitchToAccount(targetAcc?.wxid || identifier);
                } catch (e) {}
            }

            // 3. 关键修复：确保将当前选中的真实微信账号信息 100% 写入 appSettings
            if (typeof appSettings !== 'undefined') {
                appSettings.wc_current_user_id = targetAcc?.maskId || targetAcc?.wxid || identifier;
                appSettings.wc_current_user_name = targetAcc?.name || appSettings.wc_current_user_name || '微信用户';
                appSettings.wc_current_user_avatar = targetAcc?.avatar || appSettings.wc_current_user_avatar || '';
                appSettings.wc_current_user_phone = targetAcc?.wxid || targetAcc?.phone || appSettings.wc_current_user_phone || '';
                if (typeof saveAppSettings === 'function') {
                    saveAppSettings();
                }
            }

            // 4. 登录成功，解除门禁并显示底栏
            const storeUI = document.getElementById('storeAppUI');
            const bottomBar = storeUI?.querySelector('.store-app-bottom-bar');
            if (bottomBar) bottomBar.style.display = 'flex';

            await storeLoadAppearance();
            await initStoreDataFromDB();
            storeRenderMallProducts();
            storeRenderBrandStores();
            storeRenderTakeoutShops();
            storeRenderCart();
            storeSwitchOrderType('mall');
            syncUserProfile();

            storeCloseLoginSubpage();
            storeNavigate('mall');

            if (typeof showToast === 'function') {
                showToast(`已登录：${appSettings.wc_current_user_name || '微信用户'}`);
            }
        } catch (e) {
            console.error('快捷登录失败:', e);
            closeStoreApp();
            if (typeof showToast === 'function') showToast('快捷登录失败，请重试');
        }
    };

    function storeCatalogNewId(){
        const records = [...mallDatabase,...brandStoreDatabase,...takeoutDatabase,
            ...takeoutDatabase.flatMap(shop => shop.dishes || []),...cartItems];
        return Math.max(Date.now(),records.reduce((max,item) => {
            const id = Number(item.id);
            return Number.isSafeInteger(id) ? Math.max(max,id) : max;
        },0)+1);
    }
    function storeGetShopPreviewProducts(shop){
 const products=mallDatabase.filter(x=>Number(x.storeId)===Number(shop.id)),ids=new Set(products.map(x=>String(x.id)));
 return [...products,...(Array.isArray(shop.products)?shop.products:[]).filter(x=>!x.id||!ids.has(String(x.id)))].slice(0,5);
}
