    window.storeRenderCart = function () {
        const mount = document.getElementById('storeCartMount');
        const indicator = document.getElementById('storeCartCountIndicator');
        const badge = document.getElementById('storeBottomCartBadge');

        if (indicator) indicator.innerText = cartItems.length;
        if (badge) badge.innerText = cartItems.length;

        if (!mount) return;
        if (cartItems.length === 0) {
            mount.innerHTML = `<div style="text-align:center; padding:50px 0; color:#999; font-size:12px;">购物车空空如也，去逛逛吧</div>`;
            storeCalcCartTotal();
            return;
        }

        mount.innerHTML = cartItems.map((item, index) => `
            <div class="store-cart-group-card">
                <div class="store-cart-store-header">
                    <svg class="store-icon" viewBox="0 0 24 24"><path d="M20 4H4v2h16V4zm1 10v-2l-1-5H4l-1 5v2h1v6h10v-6h4v6h2v-6h1zm-9 4H6v-4h6v4z"/></svg>
                    <span>${item.store}</span>
                </div>
                <div class="store-cart-sku-row">
                    <div class="store-custom-check-circle ${item.checked ? 'store-active' : ''}" onclick="storeToggleItemSelect(${index})">
                        <svg class="store-icon" style="font-size:12px;" viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>
                    </div>
                    <img class="store-sku-thumb" ${storeSmartImageAttrs(item.img, item.title, 'product', item.photoSource || '')} alt="">
                    <div class="store-sku-body">
                        <div class="store-sku-title">${item.title}</div>
                        <div class="store-sku-desc-tag">${item.sku}</div>
                        <div class="store-sku-foot">
                            <div style="color:#ee0a24; font-weight:bold; font-size:13px;">¥${item.price.toFixed(2)}</div>
                            <div class="store-counter-group">
                                <button class="store-counter-btn" onclick="storeModifyQty(${index}, -1)">-</button>
                                <span class="store-counter-num">${item.count}</span>
                                <button class="store-counter-btn" onclick="storeModifyQty(${index}, 1)">+</button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `).join('');

        storeCalcCartTotal();
    };

    window.storeToggleItemSelect = function (idx) {
        cartItems[idx].checked = !cartItems[idx].checked;
        syncStoreDataToDB();
        storeRenderCart();
    };

    window.storeToggleSelectAllCart = function () {
        const allChecked = cartItems.every(i => i.checked);
        cartItems.forEach(i => i.checked = !allChecked);
        syncStoreDataToDB();
        storeRenderCart();
    };

    window.storeModifyQty = function (idx, step) {
        const next = cartItems[idx].count + step;
        if (next <= 0) {
            if (confirm("确定将该商品从购物车移出？")) {
                cartItems.splice(idx, 1);
            }
        } else {
            cartItems[idx].count = next;
        }
        syncStoreDataToDB();
        storeRenderCart();
    };

    window.storeCalcCartTotal = function () {
        const total = cartItems.filter(i => i.checked).reduce((s, i) => s + i.price * i.count, 0);
        const totalMount = document.getElementById('storeCartTotalMount');
        const checkCircle = document.getElementById('storeCheckAllCircle');

        if (totalMount) totalMount.innerText = total.toFixed(2);
        const allSel = cartItems.length > 0 && cartItems.every(i => i.checked);
        if (checkCircle) checkCircle.classList.toggle('store-active', allSel);
    };

    window.storeCheckoutCart = async function () {
        const checkedItems = cartItems.filter(i => i.checked);
        if (checkedItems.length === 0) {
            if (typeof showToast === 'function') showToast("请先勾选需要结算的商品！");
            else alert("请先勾选需要结算的商品！");
            return;
        }

        const firstItem = checkedItems[0];
        const total = checkedItems.reduce((s, i) => s + i.price * i.count, 0);
        const combinedTitle = checkedItems.length > 1
            ? `${firstItem.title} 等共 ${checkedItems.length} 件好物`
            : firstItem.title;
        const combinedSku = checkedItems.length > 1
            ? `包含 ${checkedItems.map(i => i.sku).join(' / ')}`
            : firstItem.sku;

        currentDetailProduct = {
            id: firstItem.id,
            storeId: checkedItems.every(item => item.storeId === firstItem.storeId) ? firstItem.storeId : null,
            storeName: checkedItems.length === 1 ? (firstItem.store || '品牌官方店') : '淘悦集官方自营',
            storeBadge: '品质自营',
            title: combinedTitle,
            price: total,
            img: firstItem.img
        };
        currentSpecName = combinedSku;
        currentSpecExtra = 0;
        currentSKUQuantity = 1;
        storeCheckoutCartDraft = JSON.parse(JSON.stringify(checkedItems));

        storeOpenCheckoutSubpage();
    };

