    window.storeSubmitReview = function (orderId) {
        const order = dummyOrders.find(o => o.id === orderId);
        const reviewTextEl = document.querySelector('.store-review-textarea');
        const contentVal = reviewTextEl ? reviewTextEl.value.trim() : '';

        // 获取选中的星级
        const activeStars = document.querySelectorAll('.store-review-star.active').length;
        const starMap = ['★☆☆☆☆', '★★☆☆☆', '★★★☆☆', '★★★★☆', '★★★★★'];
        const starStr = starMap[Math.max(0, Math.min(4, activeStars - 1))] || '★★★★★';

        if (order) {
            order.status = "finished";
            order.statusText = "已评价";

            // 将用户的真实评价存入该商品的宝贝评价中
            if (order.title) {
                const prod = mallDatabase.find(p => p.id === order.productId || p.title === order.title);
                if (prod) {
                    if (!Array.isArray(prod.reviews)) prod.reviews = [];
                    const currentUserName = (typeof appSettings !== 'undefined' && appSettings.wc_current_user_name) ? appSettings.wc_current_user_name : '买家';
                    prod.reviews.unshift({
                        user: currentUserName,
                        star: starStr,
                        date: new Date().toISOString().slice(0, 10),
                        sku: order.sku || '官方标配',
                        content: contentVal || '做工精细，实物与描述一致，非常满意！'
                    });
                }
            }

            syncStoreDataToDB();
            storeSwitchOrderType('mall');
        }

        if (typeof showToast === 'function') showToast('评价成功！已同步至商品评价');
        storeCloseReviewSubpage();
        storeOpenOrderSubpage('all');
    };

