    window.storeSaveEditTakeoutSubmit = async function () {
        if (!currentTakeoutShop) return;

        const nameVal = document.getElementById('storeEditTakeoutNameInput')?.value.trim();
        const coverVal = document.getElementById('storeEditTakeoutCoverPreview')?.src || '';
        const monthSalesVal = document.getElementById('storeEditTakeoutMonthSalesInput')?.value.trim();
        const timeVal = document.getElementById('storeEditTakeoutTimeInput')?.value.trim();

        if (!nameVal) {
            if (typeof showToast === 'function') showToast("店铺名称不能为空");
            return;
        }

        const dishRows = document.querySelectorAll('#storeEditDishesMount .store-edit-dish-row');
        const dishes = [];
        dishRows.forEach((row, idx) => {
            const name = row.querySelector('.dish-name-input')?.value.trim();
            const rawPrice = Number(row.querySelector('.dish-price-input')?.value);
            const price = Number.isFinite(rawPrice) && rawPrice >= 0 ? rawPrice : NaN;
            const desc = row.querySelector('.dish-desc-input')?.value.trim() || '现点现做 · 新鲜出炉';
            const img = row.querySelector('.dish-img-input')?.value.trim() || storeFindMatchedRealPhoto(name, 'dish');
            if (name) {
                const dishId = parseInt(row.getAttribute('data-dish-id'), 10) || (Date.now() + idx);
                const oldDish = currentTakeoutShop.dishes?.find(dish => dish.id === dishId);
                dishes.push({
                    id: dishId,
                    name,
                    price,
                    desc,
                    img,
                    photoSource: oldDish && oldDish.img === img && oldDish.photoSource
                        ? oldDish.photoSource : (row.dataset.storeDishPhotoSource || 'matched')
                });
            }
        });

        if (dishes.some(dish => !Number.isFinite(dish.price))) {
            if (typeof showToast === 'function') showToast('餐品价格必须是有效数字');
            return;
        }
        if (currentTakeoutShop.isCustom && dishes.length === 0) {
            if(typeof showToast==='function') showToast('请填写至少一道餐品名称');
            return;
        }

        currentTakeoutShop.name = nameVal;
        if (coverVal) {
            if (coverVal !== currentTakeoutShop.img) currentTakeoutShop.photoSource = 'custom';
            currentTakeoutShop.img = coverVal;
        }
        if (monthSalesVal) currentTakeoutShop.monthSales = monthSalesVal;
        if (timeVal) {
            const parts = timeVal.split('·');
            currentTakeoutShop.time = parts[0]?.trim() || '28分钟';
            currentTakeoutShop.distance = parts[1]?.trim() || '1.4km';
        }
        currentTakeoutShop.dishes = dishes;

        // 同步更新 takeoutDatabase
        const dbIdx = takeoutDatabase.findIndex(s => s.id === currentTakeoutShop.id);
        if(dbIdx>-1) takeoutDatabase[dbIdx]={...takeoutDatabase[dbIdx],...currentTakeoutShop};
        else takeoutDatabase.push(currentTakeoutShop);
        try{await storeQueueUserSnapshot();}catch(error){if(typeof showToast==='function')showToast('保存失败，请检查设备存储空间');return;}
        storeRefreshDynamicCoupons();
        storeOpenTakeoutDetailSubpage(currentTakeoutShop.id);
        storeRenderTakeoutShops();

        storeCloseEditTakeoutDrawer();
        if (typeof showToast === 'function') showToast("外卖店铺及美食信息已更新！");
    };

