    // ================= 仿截图毛玻璃封面菜单全局控制器 =================
    let currentCoverTargetType = 'product'; // 'product' | 'takeout' | 'brand' | 'dish'
    let currentCoverDishRow = null;

    window.storeOpenCoverMenu = function (targetType, event) {
        if (event) event.stopPropagation();
        if (targetType === 'dish') {
            const row = event?.currentTarget?.closest('.store-edit-dish-row');
            if (!row) return;
            currentCoverDishRow = row;
        } else {
            currentCoverDishRow = null;
        }
        currentCoverTargetType = targetType;
        const mask = document.getElementById('storeCoverGlassMenuMask');
        const panel = document.getElementById('storeCoverGlassMenuPanel');
        if (!mask || !panel) return;

        // 获取被点击封面图片的真实视口坐标，将菜单精准定位在图片附近（如截图：上边沿遮挡切入封面下半部，透出磨砂模糊色彩）
        const wrapEl = event?.currentTarget || event?.target?.closest('.store-edit-cover-center-wrap');
        if (wrapEl) {
            const rect = wrapEl.getBoundingClientRect();
            const panelWidth = 246;
            let left = rect.left + (rect.width / 2) - (panelWidth / 2);
            // 边缘防溢出控制
            const maxLeft = window.innerWidth - panelWidth - 12;
            left = Math.max(12, Math.min(maxLeft, left));

            // 1:1 模仿截图位置：让菜单顶部切入封面下部约 45% 的位置，让封面图案直接作为高斯模糊背景
            let top = rect.top + (rect.height * 0.42);
            // 若下方空间不足则贴在上方附近
            if (top + 175 > window.innerHeight) {
                top = Math.max(12, rect.bottom - 170);
                panel.style.transformOrigin = 'bottom center';
            } else {
                panel.style.transformOrigin = 'top center';
            }

            panel.style.left = `${left}px`;
            panel.style.top = `${top}px`;
        }

        mask.classList.add('show');
    };

    window.storeCloseCoverMenu = function () {
        const mask = document.getElementById('storeCoverGlassMenuMask');
        if (mask) mask.classList.remove('show');
    };

