    window.storeSaveEditProductSubmit = async function () {
        if (!currentDetailProduct) return;

        const titleVal = document.getElementById('storeEditTitleInput')?.value.trim();
        const priceVal = parseFloat(document.getElementById('storeEditPriceInput')?.value);
        const salesVal = document.getElementById('storeEditSalesInput')?.value.trim();
        const coverVal = document.getElementById('storeEditCoverPreview')?.src || '';
        const storeIdVal = parseInt(document.getElementById('storeEditProductStoreSelect')?.value, 10);

        if (!titleVal) {
            if (typeof showToast === 'function') showToast("商品标题不能为空");
            return;
        }
        if (!Number.isFinite(priceVal) || priceVal < 0) {
            if (typeof showToast === 'function') showToast("请输入有效的商品价格");
            return;
        }

        // 收集规格
        const specRows = document.querySelectorAll('#storeEditSpecsMount .store-edit-spec-row');
        const specs = [];
        specRows.forEach(row => {
            const name = row.querySelector('.spec-name-input')?.value.trim();
            const extra = parseFloat(row.querySelector('.spec-extra-input')?.value) || 0;
            if (name) {
                specs.push({ name, extra });
            }
        });
        if (specs.length === 0) {
            specs.push({ name: "官方标配 / 默认款", extra: 0 });
        }

        // 收集评价
        const reviewRows = document.querySelectorAll('#storeEditReviewsMount .store-edit-review-row');
        const reviews = [];
        reviewRows.forEach(row => {
            const user = row.querySelector('.review-user-input')?.value.trim() || '买家***';
            const star = row.querySelector('.review-star-select')?.value || '★★★★★';
            const sku = row.querySelector('.review-sku-input')?.value.trim() || (specs[0]?.name || '官方默认');
            const date = row.querySelector('.review-date-input')?.value.trim() || new Date().toISOString().slice(0, 10);
            const content = row.querySelector('.review-content-input')?.value.trim();
            if (content) {
                reviews.push({ user, star, sku, date, content });
            }
        });

        // 查找选中的目标店铺
        const targetStore = brandStoreDatabase.find(s => s.id === storeIdVal);

        // 写入当前商品对象
        currentDetailProduct.title = titleVal;
        currentDetailProduct.price = priceVal;
        if (salesVal) currentDetailProduct.sales = salesVal;
        if (coverVal) {
            if (coverVal !== currentDetailProduct.img) currentDetailProduct.photoSource = 'custom';
            currentDetailProduct.img = coverVal;
            delete document.getElementById('storeEditCoverPreview')?.dataset.storeCoverGenerated;
        }
        currentDetailProduct.specs = specs;
        currentDetailProduct.reviews = reviews;

        if (targetStore) {
            currentDetailProduct.storeId = targetStore.id;
            currentDetailProduct.storeName = targetStore.name;
            currentDetailProduct.storeBadge = targetStore.badge || '官方认证';
            currentDetailProduct.storeDesc = targetStore.desc || '官方正品';
            currentDetailProduct.storeLogo = (targetStore.name || '').slice(0, 4).toUpperCase();
        }

        // 同步更新 mallDatabase 里的真实商品记录
        const dbIdx = mallDatabase.findIndex(p => p.id === currentDetailProduct.id);
        if(dbIdx>-1)mallDatabase[dbIdx]={...mallDatabase[dbIdx],...currentDetailProduct};
        else mallDatabase.push(currentDetailProduct);

        // Keep store listings, cart and browsing thumbnails in sync with the edited product.
        brandStoreDatabase.forEach(shop => {
            (shop.products || []).forEach(item => {
                if (String(item.id) !== String(currentDetailProduct.id) ||
                    String(shop.id) !== String(currentDetailProduct.storeId)) return;
                item.title = currentDetailProduct.title;
                item.price = String(currentDetailProduct.price);
                item.img = currentDetailProduct.img;
                item.photoSource = currentDetailProduct.photoSource;
            });
        });
        [...cartItems, ...browseHistory].forEach(item => {
            if (String(item.id) !== String(currentDetailProduct.id)) return;
            item.img = currentDetailProduct.img;
            item.title = currentDetailProduct.title;
        });

        // Do not claim success if a large generated image exceeds the current store limit.
        try{await storeQueueUserSnapshot();}catch(error){
            if (typeof showToast === 'function') showToast('保存失败：存储空间可能不足，请换一张较小的图片');
            return;
        }
        storeOpenGoodsDetail(currentDetailProduct.id);
        storeRenderMallProducts();
        storeRenderBrandStores();

        storeCloseEditProductDrawer();
        storeRefreshDynamicCoupons();
        if (typeof showToast === 'function') {
            showToast("商品信息已成功更新！");
        }
    };

