    // 真实网购评价动态解析器：从原始文本中强壮提取 JSON 数组
    function storeExtractReviewsJson(text) {
        if (!text || typeof text !== 'string') return null;
        const cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
        const jsonStart = cleaned.indexOf('[');
        const jsonEnd = cleaned.lastIndexOf(']');
        if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
            try {
                const arr = JSON.parse(cleaned.slice(jsonStart, jsonEnd + 1));
                if (Array.isArray(arr) && arr.length > 0) return arr;
            } catch (e) {}
        }
        return null;
    }

    window.storeExecuteFreeAIReviewGen = async function () {
        if (!currentDetailProduct) {
            if (typeof showToast === 'function') showToast('商品数据加载异常');
            return;
        }

        const channel = freeAIChannels.find(c => c.id === currentSelectedFreeChannelId) || freeAIChannels[0];
        const urlVal = document.getElementById('storeFreeApiUrlInput')?.value.trim() || channel.url;
        const modelVal = document.getElementById('storeFreeApiModelInput')?.value.trim() || channel.model;

        // 立即关闭设置弹窗，不让弹窗展示正在生成
        storeCloseFreeAIReviewModal();

        // 唤起页面上半部分的悬浮灵动胶囊提示
        const topIsland = document.getElementById('storeTopIslandPill');
        const topIslandText = document.getElementById('storeTopIslandText');
        if (topIsland) {
            if (topIslandText) topIslandText.innerText = "正在努力生成商品评价...";
            topIsland.classList.add('show');
        }

        const specs = Array.isArray(currentDetailProduct.specs) ? currentDetailProduct.specs.map(s => s.name) : ['默认规格'];
        const specListStr = specs.join('、');
        const randSeed = Math.floor(Math.random() * 9999999);

        // 核心提示词：彻底打破清一色好评与死板套话！
        const prompt = `你是一个真实电商平台（如淘宝、得物、京东）的真实买家群体模拟器。
请根据下列当前宝贝的真实信息：
- 宝贝名称：【${currentDetailProduct.title}】
- 真实价格：¥${(currentDetailProduct.price || 99).toFixed(2)}
- 所属店铺：【${currentDetailProduct.storeName || '品牌店'}】
- 可选规格/SKU：【${specListStr}】

请为该宝贝生成 ${freeReviewGenerateCount} 条【完全不同买家性格、不同打星、不同立场的真实买家评价】！

【极其严格的生态要求】：
1. 严禁全部写五星好评！真实电商评价必有分歧！
   必须包含下列不同星级与态度：
   - 包含【1星或2星差评/踩雷吐槽】（如：实物有色差/偏大偏小偏码/做工毛刺溢胶/续航尿崩/底噪大/包装压烂/性价比低等真实痛点吐槽，语气暴躁或失望！）；
   - 包含【3星或4星中评/中肯客观】（如：优点是什么，但某个细节做工或物流有待改进，不吹不黑）；
   - 包含【5星真实好评/真香买家秀】（真实赞赏某个具体功能或使用体验，绝不说空泛套话）。
2. 每条评价必须指名道姓提到该商品的具体功能或外观材质（如鞋底回弹、降噪开关、键帽轴体、面霜质地等），严禁千篇一律的套话！
3. star 字段必须是实打实的星星符号：
   - 1星："★☆☆☆☆"
   - 2星："★★☆☆☆"
   - 3星："★★★☆☆"
   - 4星："★★★★☆"
   - 5星："★★★★★"
4. 每条评价分配不同的真实买家脱敏昵称（如：阿***白、退***客、挑***生、早***睡）、近两个月的真实日期（YYYY-MM-DD），并在可选规格中挑选具体 SKU。

请直接返回合法的 JSON 数组，严禁包含任何前缀解释或 markdown 代码块：
[
  {
    "user": "买家昵称",
    "star": "★☆☆☆☆",
    "date": "2026-03-24",
    "sku": "${specs[0] || '默认'}",
    "content": "具体的真实踩雷吐槽或好评中评..."
  }
]`;

        let parsed = null;

        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 25000);

            // 免 Key 线上公开模型通道（POST 与 极速 GET 双保险）
            const resp = await fetch('https://text.pollinations.ai/', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                signal: controller.signal,
                body: JSON.stringify({
                    messages: [
                        { role: 'system', content: 'You output ONLY a raw JSON array of realistic Chinese e-commerce reviews with mixed stars (1 to 5 stars, including critical complaints and honest praise). No markdown.' },
                        { role: 'user', content: prompt }
                    ],
                    model: modelVal || 'qwen',
                    seed: randSeed,
                    jsonMode: true
                })
            }).catch(() => null);

            clearTimeout(timeoutId);

            if (resp && resp.ok) {
                const text = await resp.text();
                parsed = storeExtractReviewsJson(text);
            }

            // 若 POST 未拿到，走极速免密通道
            if (!parsed) {
                const fastUrl = `https://text.pollinations.ai/${encodeURIComponent(prompt)}?model=${encodeURIComponent(modelVal || 'qwen')}&seed=${randSeed}&json=true`;
                const getResp = await fetch(fastUrl).catch(() => null);
                if (getResp && getResp.ok) {
                    const getText = await getResp.text();
                    parsed = storeExtractReviewsJson(getText);
                }
            }
        } catch (e) {
            console.warn('模型请求发生异常:', e);
        } finally {
            // 无论成功还是失败，均隐藏顶部悬浮灵动胶囊
            if (topIsland) topIsland.classList.remove('show');
        }

        // 如果大模型未能成功返回或解析失败，坚决不使用任何伪造模板，直接提示失败并终止！
        if (!parsed || !Array.isArray(parsed) || parsed.length === 0) {
            if (typeof showToast === 'function') {
                showToast('大模型接口繁忙，请重试或切换其他模型');
            } else {
                alert('大模型接口繁忙，请重试或切换其他模型');
            }
            return;
        }

        // 把真实生成的评价追加进商品评价库
        const oldReviews = Array.isArray(currentDetailProduct.reviews) ? currentDetailProduct.reviews : [];
        currentDetailProduct.reviews = [...parsed, ...oldReviews];

        const dbIdx = mallDatabase.findIndex(p => p.id === currentDetailProduct.id);
        if (dbIdx > -1) {
            mallDatabase[dbIdx].reviews = currentDetailProduct.reviews;
        }
        syncStoreDataToDB();

        // 立即刷新前台评价列表及详情页显示
        storeRenderProductReviewsList();
        storeOpenGoodsDetail(currentDetailProduct.id);

        if (typeof showToast === 'function') {
            showToast(`已成功生成 ${parsed.length} 条真实评价（包含好评、中评与差评吐槽）！`);
        }
    };

