    window.storeSwitchTakeoutCategory = function (el, cat) {
        document.querySelectorAll('.store-takeout-menu-item').forEach(m => m.classList.remove('active'));
        if (el) el.classList.add('active');
        storeRenderTakeoutDishes();
    };

    function storeGetDishItemById(dishId) {
        const dishes = (currentTakeoutShop && Array.isArray(currentTakeoutShop.dishes))
            ? currentTakeoutShop.dishes
            : dummyDishes;
        return dishes.find(d => d.id === dishId);
    }

    window.storeRenderTakeoutDishes = function () {
        const mount = document.getElementById('storeTakeoutDishesMount');
        if (!mount) return;

        const dishes = (currentTakeoutShop && Array.isArray(currentTakeoutShop.dishes))
            ? currentTakeoutShop.dishes
            : dummyDishes;

        mount.innerHTML = dishes.map(dish => {
            const inCart = takeoutCartItems.find(i => i.id === dish.id);
            const count = inCart ? inCart.count : 0;
            return `
            <div class="store-dish-card">
                <img class="store-dish-thumb" ${storeSmartImageAttrs(dish.img, dish.name, 'dish', dish.photoSource || '')} alt="">
                <div class="store-dish-info">
                    <div>
                        <div class="store-dish-name">${dish.name}</div>
                        <div class="store-dish-desc">${dish.desc}</div>
                    </div>
                    <div class="store-dish-bottom">
                        <div class="store-dish-price">¥${(dish.price || 20).toFixed(2)}</div>
                        <div class="store-dish-action-box">
                            ${count > 0 ? `
                                <button type="button" class="store-dish-step-btn minus" onclick="storeModifyTakeoutDishQty(${dish.id}, -1)">−</button>
                                <span class="store-dish-step-num">${count}</span>
                            ` : ''}
                            <button type="button" class="store-dish-step-btn plus" onclick="storeModifyTakeoutDishQty(${dish.id}, 1)">+</button>
                        </div>
                    </div>
                </div>
            </div>
            `;
        }).join('');
    };

    window.storeModifyTakeoutDishQty = function (dishId, delta) {
        const dish = storeGetDishItemById(dishId);
        if (!dish) return;

        let existing = takeoutCartItems.find(i => i.id === dishId);
        if (!existing && delta > 0) {
            existing = {
                id: dish.id,
                name: dish.name,
                price: parseFloat(dish.price) || 20.00,
                desc: dish.desc || '',
                img: storeResolveSmartImage({ title: dish.name, img: dish.img, type: 'dish' }),
                count: 0
            };
            takeoutCartItems.push(existing);
        }

        if (existing) {
            existing.count += delta;
            if (existing.count <= 0) {
                takeoutCartItems = takeoutCartItems.filter(i => i.id !== dishId);
            }
        }

        storeUpdateTakeoutCartBar();
        storeRenderTakeoutDishes();
    };

    function storeUpdateTakeoutCartBar() {
        takeoutCartTotal = takeoutCartItems.reduce((sum, item) => sum + item.price * item.count, 0);
        const totalMount = document.getElementById('storeTakeoutCartTotalMount');
        if (totalMount) totalMount.innerText = takeoutCartTotal.toFixed(2);
    }

    // 打开独立外卖确认订单页面（显示真实的选购餐品）
    window.storeCheckoutTakeoutOrder = function () {
        if (takeoutCartItems.length === 0 || takeoutCartTotal <= 0) {
            if (typeof showToast === 'function') showToast("请先选购您想吃的美食！");
            else alert("请先选购您想吃的美食！");
            return;
        }

        const page = document.getElementById('storeTakeoutCheckoutSubpage');
        if (!page) return;
        storeBringSubpageToFront(page);

        const shop = currentTakeoutShop || takeoutDatabase[0];
        const shopTitle = shop.name;

        // 真实复制用户选购的菜品清单，彻底替换假切片
        currentTakeoutOrderDraft = {
            shop: shop,
            foodTotal: takeoutCartTotal,
            packingFee: 2.00,
            deliveryFee: shop.deliveryFee?.includes('免') ? 0.00 : 3.00,
            items: JSON.parse(JSON.stringify(takeoutCartItems))
        };

        const subtotal = currentTakeoutOrderDraft.foodTotal + currentTakeoutOrderDraft.packingFee + currentTakeoutOrderDraft.deliveryFee;

        // 自动匹配最优惠的外卖可用券
        selectedTakeoutCoupon = storeFindBestAvailableCoupon('takeout', subtotal, shop.id);

        document.getElementById('storeTakeoutCheckoutShopTitle').innerText = shopTitle;
        const itemsMount = document.getElementById('storeTakeoutCheckoutItemsList');
        if (itemsMount) {
            itemsMount.innerHTML = currentTakeoutOrderDraft.items.map(dish => `
                <div class="store-order-prod-row" style="margin-bottom:10px; align-items:center;">
                    <img ${storeSmartImageAttrs(dish.img, dish.name, 'dish', dish.photoSource || '')} style="width:48px; height:48px; border-radius:8px; object-fit:cover;" alt="">
                    <div class="store-order-prod-info">
                        <div class="store-order-prod-title" style="font-size:13.5px; font-weight:700;">${dish.name}</div>
                        <div class="store-order-prod-sku">${dish.desc || '现做现发 · 香气四溢'}</div>
                        <div style="display:flex; justify-content:space-between; align-items:center;">
                            <div style="font-size:13.5px; font-weight:800; color:#1d1d1f;">¥${dish.price.toFixed(2)}</div>
                            <span style="font-size:12px; color:#8e8e93; font-weight:600;">x${dish.count}</span>
                        </div>
                    </div>
                </div>
            `).join('');
        }

        const feeTxt = document.getElementById('storeTakeoutCheckoutDeliveryFeeTxt');
        if (feeTxt) feeTxt.innerText = currentTakeoutOrderDraft.deliveryFee === 0 ? '免配送费' : `¥${currentTakeoutOrderDraft.deliveryFee.toFixed(2)}`;

        storeUpdateTakeoutCheckoutPriceDisplay(subtotal);

        const defaultAddr = addressList.find(a => a.isDefault) || addressList[0];
        const nameEl = document.getElementById('storeTakeoutCheckoutAddrName');
        const detailEl = document.getElementById('storeTakeoutCheckoutAddrDetail');
        if (defaultAddr) {
            selectedCheckoutAddressId = defaultAddr.id;
            if (nameEl) nameEl.innerHTML = `${defaultAddr.name} <span style="font-weight:normal; color:#8e8e93; font-size:12px;">${defaultAddr.tel}</span>`;
            if (detailEl) detailEl.innerText = defaultAddr.detail;
        } else {
            selectedCheckoutAddressId = null;
            if (nameEl) nameEl.innerText = "请选择收货地址";
            if (detailEl) detailEl.innerText = "点击选择或添加送餐地址";
        }

        page.classList.add('store-subpage-active');
    };

    window.storeCloseTakeoutCheckoutSubpage = function () {
        const page = document.getElementById('storeTakeoutCheckoutSubpage');
        if (page) page.classList.remove('store-subpage-active');
    };

    // 外卖结算页面立即支付按钮：直接调取内部支付弹窗
    window.storeSubmitTakeoutPay = async function () {
        if (!currentTakeoutOrderDraft) return;
        const payNum = Math.round(Math.max(0, currentTakeoutOrderDraft.foodTotal +
            currentTakeoutOrderDraft.packingFee + currentTakeoutOrderDraft.deliveryFee -
            (Number(selectedTakeoutCoupon?.value) || 0)) * 100) / 100;
        const shopTitle = currentTakeoutOrderDraft.shop.name;
        const now = new Date();
        const timeStr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
        const remarkText = document.getElementById('storeTakeoutRemarkInput')?.value.trim() || '';

        // 生成专属真实外卖订单：注入真实餐品、骑手信息、配送路线数据及备注
        const takeoutItems = currentTakeoutOrderDraft?.items || [];
        const summaryTitle = takeoutItems.length > 0
            ? `${takeoutItems[0].name}${takeoutItems.length > 1 ? ` 等共 ${takeoutItems.reduce((s,i)=>s+i.count,0)} 件餐品` : ` x${takeoutItems[0].count}`}`
            : `${shopTitle} 精品美食外卖`;

        // 随机外卖取餐与配送时间（现实生活非固定时间）
        const randFetchMins = Math.floor(Math.random() * 10) + 3; // 3 ~ 12 分钟取餐
        const randDeliveryMins = Math.floor(Math.random() * 22) + 15; // 15 ~ 36 分钟送达
        const totalEst = randFetchMins + randDeliveryMins;

        const targetStatus = "undelivered";
        const targetStatusText = "骑手正在取餐";

        const currentAddr = addressList.find(a => a.id === selectedCheckoutAddressId) || addressList.find(a => a.isDefault) || addressList[0] || {
            name: "默认收货人", tel: "13800000000", detail: "尚未配置送餐地址"
        };

        const pendingOrder = {
            id: storeNewOrderId('WM'),
            orderCategory: 'takeout',
            storeId: currentTakeoutOrderDraft?.shop?.id || 201,
            store: shopTitle,
            status: 'unpaid',
            statusText: targetStatusText,
            title: summaryTitle,
            sku: selectedTakeoutCoupon ? `已用券抵扣 -¥${selectedTakeoutCoupon.value}` : "专送服务 · 准时达保障",
            price: payNum,
            totalAmount: payNum,
            count: takeoutItems.reduce((s,i)=>s+i.count,0) || 1,
            img: currentTakeoutOrderDraft?.shop?.img || storeGenerateCoverSvg('#d1d1d6'),
            address: {
                name: currentAddr.name,
                tel: currentAddr.tel,
                detail: currentAddr.detail,
                targetType: currentAddr.targetType || 'user',
                targetCharId: currentAddr.targetCharId || null,
                targetCharName: currentAddr.targetCharName || null
            },
            createdAt: timeStr,
            paidAt: Date.now(),
            mapStep: 1,
            timeConfig: {
                fetchMinutes: randFetchMins,
                totalMinutes: totalEst
            },
            remark: remarkText,
            takeoutItems: takeoutItems,
            rider: {
                name: "骑手",
                role: "骑手",
                rating: (4.7 + Math.random() * 0.29).toFixed(1),
                distance: `距商家 ${(Math.random() * 1.5 + 0.3).toFixed(1)} 公里`,
                eta: `预计 ${totalEst} 分钟内送达`
            }
        };
        await storeRequestOrderPayment(pendingOrder, () => {
            // 清空当前点餐购物车
            takeoutCartItems = [];
            takeoutCartTotal = 0;
            storeUpdateTakeoutCartBar();
            storeRenderTakeoutDishes();

            storeSwitchOrderType('mall');

            if (typeof showToast === 'function') showToast(`外卖支付成功！实付 ¥${payNum.toFixed(2)}，专送骑手已接单`);
            storeCloseTakeoutCheckoutSubpage();
            storeCloseTakeoutDetailSubpage();
            storeOpenOrderSubpage(targetStatus);
        }, `外卖点餐 - ${shopTitle.slice(0, 15)}`);
    };

