    // ================= 优惠券核心辅助与业务逻辑 =================
    function storeFindBestAvailableCoupon(type, amount, storeId = null) {
        storeRefreshDynamicCoupons();
        const available = builtInCouponTemplates.filter(c => {
            if (!userClaimedCouponIds.includes(c.id)) return false;
            if (c.type !== type) return false;
            if (amount < c.min) return false;
            // 严格防穿透：优惠减免金额绝对不能大于等于商品总额（防止倒贴/0元）
            if (c.value >= amount) return false;
            if (c.storeId && c.storeId !== storeId) return false;
            return true;
        });
        if (available.length === 0) return null;
        available.sort((a, b) => b.value - a.value);
        return available[0];
    }

