    // ================= 限时抢购与好友拼单核心引擎 (0 Token 伪随机每日轮换) =================
    let currentFlashTab = 'direct'; // 'direct' | 'group'
    let activePinSessions = {}; // 存储活跃拼单: { [pinId]: { id, title, price, origPrice, img, storeName, targetContactId, contactName, isCompleted, category } }
    let flashCountdownInterval = null;

    // 辅助函数：根据日期字符串与偏移量生成稳定伪随机浮点数 (0~1)
    function storeGetDailyPrng(salt = 0) {
        const todayStr = new Date().toISOString().slice(0, 10); // 例如 "2026-03-24"
        let hash = 0;
        const combined = todayStr + '_' + salt;
        for (let i = 0; i < combined.length; i++) {
            hash = (hash << 5) - hash + combined.charCodeAt(i);
            hash |= 0;
        }
        return Math.abs((Math.sin(hash) * 10000) % 1);
    }

    // 动态提取今日的限时秒杀直降池与拼单池
    function storeGetDailyFlashPool() {
        const directList = [];
        const groupList = [];

        // 1. 从商城好物中抽取
        const mallItems = Array.isArray(mallDatabase) && mallDatabase.length > 0 ? mallDatabase : [];
        if (mallItems.length > 0) {
            mallItems.forEach((item, idx) => {
                const randVal1 = storeGetDailyPrng(item.id * 13 + 7);
                const randVal2 = storeGetDailyPrng(item.id * 31 + 19);

                // 每件商品根据今天的日期哈希计算是否入选直降（约 40% 概率）
                if (randVal1 > 0.55 || directList.length < 2) {
                    const discountRate = 0.4 + Math.round(randVal1 * 25) / 100; // 0.40 ~ 0.65 折扣
                    const flashPrice = Math.max(9.9, Math.round(item.price * discountRate * 10) / 10);
                    directList.push({
                        id: item.id,
                        title: item.title,
                        origPrice: item.price,
                        price: flashPrice,
                        img: item.img,
                        storeName: item.storeName || '官方旗舰店',
                        category: 'mall',
                        stockRate: Math.min(95, Math.max(55, Math.round(randVal1 * 100))),
                        tag: `限时直降 ${Math.round(discountRate * 10)}折`
                    });
                }

                // 计算是否入选双人拼单（骨折半价，约 35% 概率）
                if (randVal2 > 0.6 || groupList.length < 2) {
                    const pinRate = 0.3 + Math.round(randVal2 * 20) / 100; // 0.30 ~ 0.50 骨折价
                    const pinPrice = Math.max(5.9, Math.round(item.price * pinRate * 10) / 10);
                    groupList.push({
                        id: item.id,
                        title: item.title,
                        origPrice: item.price,
                        price: pinPrice,
                        img: item.img,
                        storeName: item.storeName || '官方旗舰店',
                        category: 'mall',
                        saveMoney: (item.price - pinPrice).toFixed(1),
                        tag: '双人特惠团'
                    });
                }
            });
        }

        // 2. 从外卖菜品库中抽取招牌美食
        const takeoutShops = Array.isArray(takeoutDatabase) && takeoutDatabase.length > 0 ? takeoutDatabase : [];
        takeoutShops.forEach((shop, sIdx) => {
            const dishes = Array.isArray(shop.dishes) ? shop.dishes : [];
            dishes.slice(0, 2).forEach((dish, dIdx) => {
                const randVal = storeGetDailyPrng((sIdx + 1) * 73 + dIdx * 41);
                const dishPrice = dish.price || 28;
                if (randVal > 0.45) {
                    const directPrice = Math.max(9.9, Math.round(dishPrice * 0.55 * 10) / 10);
                    directList.push({
                        id: dish.id || (shop.id * 10 + dIdx),
                        title: `${dish.name}（${shop.name.slice(0, 8)}）`,
                        origPrice: dishPrice,
                        price: directPrice,
                        img: dish.img || shop.img,
                        storeName: shop.name,
                        category: 'takeout',
                        stockRate: Math.min(96, Math.max(60, Math.round(randVal * 100))),
                        tag: '外卖爆款秒杀'
                    });
                } else {
                    const pinPrice = Math.max(6.9, Math.round(dishPrice * 0.4 * 10) / 10);
                    groupList.push({
                        id: dish.id || (shop.id * 10 + dIdx),
                        title: `${dish.name}（${shop.name.slice(0, 8)}）`,
                        origPrice: dishPrice,
                        price: pinPrice,
                        img: dish.img || shop.img,
                        storeName: shop.name,
                        category: 'takeout',
                        saveMoney: (dishPrice - pinPrice).toFixed(1),
                        tag: '好友拼好饭'
                    });
                }
            });
        });

        return { directList, groupList };
    }

