    function storeStartFlashCountdown() {
        if (flashCountdownInterval) clearInterval(flashCountdownInterval);
        const updateTimer = () => {
            const now = new Date();
            const tomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0);
            const diffMs = Math.max(0, tomorrow.getTime() - now.getTime());

            const hours = String(Math.floor(diffMs / (1000 * 60 * 60))).padStart(2, '0');
            const minutes = String(Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60))).padStart(2, '0');
            const seconds = String(Math.floor((diffMs % (1000 * 60)) / 1000)).padStart(2, '0');

            const hEl = document.getElementById('storeFlashHour');
            const mEl = document.getElementById('storeFlashMin');
            const sEl = document.getElementById('storeFlashSec');
            if (hEl) hEl.innerText = hours;
            if (mEl) mEl.innerText = minutes;
            if (sEl) sEl.innerText = seconds;
        };
        updateTimer();
        flashCountdownInterval = setInterval(updateTimer, 1000);
    }

