    // 发起拼单新流程：先支付！支付成功后生成已付款拼单订单，进入拼单全屏页，在里面邀请好友
    let currentPinInitiatingItem = null;
    window.storeStartGroupPin = async function (item) {
        const existingPin = Object.values(activePinSessions).find(p => p.id === item.id);
        if (existingPin) {
            storeOpenPinDetailSubpage(existingPin.pinId);
            return;
        }
        currentPinInitiatingItem = item;
        const pinId = storeNewOrderId('pin_');
        const payNum = Number(item.price);
        const pinSession = {
            pinId: pinId,
            id: item.id,
            title: item.title,
            price: item.price.toFixed(2),
            origPrice: item.origPrice.toFixed(2),
            img: item.img,
            storeName: item.storeName || '双人拼单专区',
            category: item.category || 'mall',
            targetContactId: null,
            contactName: '好友',
            isPaid: true,
            isCompleted: false,
            createdAt: Date.now()
        };

        const now = new Date();
        const timeStr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
        const defaultAddr = addressList.find(a => a.isDefault) || addressList[0] || {
            name: "默认收货人", tel: "13800000000", detail: "尚未配置收货地址"
        };

        // 在我的订单中插入一条真实已付款拼单订单
        const pinOrder = {
            id: storeNewOrderId('PIN'),
            orderCategory: item.category || 'mall',
            isPinOrder: true,
            pinId: pinId,
            storeId: item.storeId || 301,
            store: item.storeName || "双人拼单专区",
            status: 'unpaid',
            statusText: "拼单中 · 待成团",
            title: `【双人拼单】${item.title}`,
            sku: "双人特惠拼单款 (已付款)",
            price: payNum,
            totalAmount: payNum,
            count: 1,
            img: item.img,
            address: {
                name: defaultAddr.name,
                tel: defaultAddr.tel,
                detail: defaultAddr.detail,
                targetType: defaultAddr.targetType || 'user',
                targetCharId: defaultAddr.targetCharId || null,
                targetCharName: defaultAddr.targetCharName || null
            },
            createdAt: timeStr,
            paidAt: Date.now(),
            mapStep: 1
        };
        await storeRequestOrderPayment(pinOrder, () => {
            storeSwitchOrderType('mall');
            storeRenderFlashSaleList();
            if (typeof showToast === 'function') showToast(`拼单付款成功 ¥${payNum.toFixed(2)}，请邀请好友成团`);
            storeOpenPinDetailSubpage(pinId);
        }, `发起双人拼单 - ${item.title.slice(0, 15)}`, pinSession);
    };

