    window.storeClaimGoodsCoupon = function (couponId) {
        if (userClaimedCouponIds.includes(couponId)) {
            if (typeof showToast === 'function') showToast('您已领过该券');
            return;
        }
        userClaimedCouponIds.push(couponId);
        syncStoreDataToDB();
        storeOpenGoodsCouponDrawer();
        if (typeof showToast === 'function') showToast('优惠券领取成功！下单自动抵扣');
    };

